import fitz

# Paper 1: Check specifically for the paper's own arXiv ID and any footnote references
doc = fitz.open("/root/redacted/paper1.pdf")
all_text = ""
for pg_num in range(doc.page_count):
    all_text += doc[pg_num].get_text()

# Check for the paper's own arXiv ID
if "2509.26542" in all_text:
    idx = all_text.index("2509.26542")
    print(f"FOUND paper's arXiv ID: ...{all_text[max(0,idx-50):idx+50]}...")
else:
    print("Paper 1's arXiv ID (2509.26542) successfully redacted")

# Check the self-citation context more carefully
for name in ["Yueqian Lin"]:
    start = 0
    while True:
        idx = all_text.find(name, start)
        if idx == -1:
            break
        context = all_text[max(0,idx-80):idx+len(name)+80].replace('\n', ' ')
        print(f"\nSelf-citation context: ...{context}...")
        start = idx + 1

